def _strip_md_indent(html):
    """
    Streamlit's Markdown parser treats any line with 4+ leading spaces as a code block,
    even inside HTML with unsafe_allow_html=True. This strips 4-space multiples to max 3.
    """
    lines = []
    for line in html.split('\n'):
        stripped = line.lstrip(' ')
        spaces = len(line) - len(stripped)
        if spaces >= 4:
            new_spaces = spaces % 4
            if new_spaces == 0:
                new_spaces = 3
            line = ' ' * new_spaces + stripped
        lines.append(line)
    return '\n'.join(lines)

def _md(html, **kw):
    """Render HTML in st.markdown, stripping 4-space indentation that breaks Markdown."""
    st.markdown(_strip_md_indent(html), unsafe_allow_html=True, **kw)

