    prev_avgs = compute_prev_year_avg(df, selected_year)

    def _spark_path(df_all, var, y_min=None, y_max=None):
        """Generate SVG path d-attribute for a sparkline from historical data."""
        series = df_all.groupby('year')[var].mean().sort_index()
        # Drop NaN values to avoid malformed SVG paths that break Streamlit HTML rendering
        series = series.dropna()
        vals = series.values.tolist()
        if len(vals) < 2:
            return "M0,22 L120,22", "M0,22 L120,22 L120,40 L0,40 Z"
        lo = min(vals) if y_min is None else y_min
        hi = max(vals) if y_max is None else y_max
        rng = max(hi - lo, 0.001)
        n = len(vals)
        pts = []
        for i, v in enumerate(vals):
            x = i / (n - 1) * 120
            y = 40 - ((v - lo) / rng) * 36
            pts.append((x, y))
        # Smooth curve via simple average
        d = f"M{pts[0][0]:.1f},{pts[0][1]:.1f}"
        for i in range(1, len(pts)):
            cx = (pts[i-1][0] + pts[i][0]) / 2
            d += f" Q{pts[i-1][0]:.1f},{pts[i-1][1]:.1f} {cx:.1f},{(pts[i-1][1]+pts[i][1])/2:.1f}"
        d += f" L{pts[-1][0]:.1f},{pts[-1][1]:.1f}"
        area = d + f" L{pts[-1][0]:.1f},40 L{pts[0][0]:.1f},40 Z"
        return d, area

    def _delta_html(delta, higher_is_good, selected_year, fmt="{:.2f}"):
        if delta is None:
            return f'<div class="kpi-driver-delta" style="color:#4B5563;">— baseline year</div>'
        improving = (delta > 0) == higher_is_good
        cls = "kpi-delta-good" if improving else "kpi-delta-bad"
        icon_name = "ti-arrow-up" if delta > 0 else "ti-arrow-down"
        return (f'<div class="kpi-driver-delta {cls}">'
                f'<i class="ti {icon_name}" style="font-size:10px;"></i>'
                f'<span>{fmt.format(abs(delta))} vs {selected_year-1}</span>'
                f'</div>')

    # Pre-compute sparkline paths for all 5 drivers
    sp_gdp_line, sp_gdp_area  = _spark_path(df, 'gdp_per_capita')
    sp_und_line, sp_und_area  = _spark_path(df, 'undernourishment_pct')
    sp_wat_line, sp_wat_area  = _spark_path(df, 'water_access_pct')
    sp_edu_line, sp_edu_area  = _spark_path(df, 'female_edu_pct')
    sp_stb_line, sp_stb_area  = _spark_path(df, 'political_stability')

    # Compute deltas
    d_gdp  = None if not prev_avgs else avgs['gdp']           - prev_avgs['gdp']
    d_und  = None if not prev_avgs else avgs['undernourishment'] - prev_avgs['undernourishment']
    d_wat  = None if not prev_avgs else avgs['water']          - prev_avgs['water']
    d_edu  = None if not prev_avgs else avgs['edu']            - prev_avgs['edu']
    d_stb  = None if not prev_avgs else avgs['stability']      - prev_avgs['stability']

    delta_gdp = _delta_html(d_gdp, True,  selected_year, "${:,.0f}")
